  perspektive = "mitglied",
  ueberschriftEbene,
}) {
  const [e, setE] = useState({ ...RECHNER_STANDARD });
  const set = (k) => (v) => setE((a) => ({ ...a, [k]: v }));
  const r = useMemo(() => rechnerOeffentlich(e), [e]);
